def isbn_valid(s: str) -> bool:
    if not isinstance(s, str):
        return False
    t = s.replace('-', '').replace(' ', '')

    if len(t) == 10:
        if not t[:9].isdigit() or not all(c in '0123456789' for c in t[:9]):
            return False
        last = t[9]
        if last == 'X':
            vals = [int(c) for c in t[:9]] + [10]
        elif last in '0123456789':
            vals = [int(c) for c in t]
        else:
            return False
        total = sum((i + 1) * v for i, v in enumerate(vals))
        return total % 11 == 0

    if len(t) == 13:
        if not all(c in '0123456789' for c in t):
            return False
        total = sum(int(c) * (1 if i % 2 == 0 else 3) for i, c in enumerate(t))
        return total % 10 == 0

    return False
```

Note: `isdigit()` is backed up by an explicit ASCII-digit check so that Unicode digit characters (e.g. superscripts or Arabic-Indic digits) are rejected rather than accepted.
